# a Properties file: empty = the file does not exist, null = it exists (or can't be told apart) and could not be read
M(cfg, r"""
public static java.util.Properties readProps(java.nio.file.Path f) {
  try {
    java.util.Properties p = new java.util.Properties();
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
      java.io.InputStream in = java.nio.file.Files.newInputStream(f, new java.nio.file.OpenOption[0]);
      try { p.load(in); } finally { in.close(); }
    } else if (!java.nio.file.Files.notExists(f, new java.nio.file.LinkOption[0])) {
      return null;
    }
    return p;
  } catch (Throwable t) { return null; }
}""")
# the keys the kit's change log names (columns time/name/uuid/via/key/old/new/status: key = column 5), the live file + its 3 rotated
# copies (config-changes.log.1-3), leaving out the lines written by `skip` (this step's own name: a set whose save was lost must be
# tried again); null = one of them exists but can't be read (then nobody can tell whether an admin set a value - the step waits)
M(cfg, r"""
public static java.util.HashSet loggedKeys(java.nio.file.Path log, String skip) {
  java.util.HashSet keys = new java.util.HashSet();
  for (int n = 0; n <= 3; n++) {
    java.nio.file.Path f = n == 0 ? log : log.resolveSibling(log.getFileName().toString() + "." + n);
    try {
      if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
        String[] ls = new String(java.nio.file.Files.readAllBytes(f), "UTF-8").split("\n");
        for (int i = 0; i < ls.length; i++) {
          String[] c = ls[i].split("\t");
          if (c.length < 5 || c[4].trim().length() == 0) continue;
          if (skip != null && c[1].trim().equals(skip)) continue;
          keys.add(c[4].trim());
        }
      } else if (!java.nio.file.Files.notExists(f, new java.nio.file.LinkOption[0])) {
        return null;
      }
    } catch (Throwable x) { return null; }
  }
  return keys;
}""")
# printable ASCII only, max n characters (values quoted in log lines and in migrations.properties); a backslash becomes '?' too
# (0.5.3 review: Properties.load reads '\' as an escape - an admin value holding "\u" with fewer than 4 hex digits would make
# migrations.properties unreadable)
M(cfg, r"""
public static String plain(String v, int n) {
  if (v == null) return "";
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < v.length() && sb.length() < n; i++) {
    char c = v.charAt(i);
    if (c >= ' ' && c < 127 && c != '\\') sb.append(c); else sb.append('?');
  }
  return sb.toString();
}""")
# -1 = nothing to do this start (the step already ran, or a file can't be read: it runs again next start); else a bit mask over
# MIG_KEYS of the lines that are still EXACTLY the old default and that no admin ever set (config-changes.log never names them).
# MIG_NOTE holds the outcome text of every key.
M(cfg, r"""
public static int plan053() {
  try {
    if (FILE == null) return -1;
    java.nio.file.Path mk = FILE.resolveSibling("migrations.properties");
    java.util.Properties done = readProps(mk);
    if (done == null) { @PKG@.IslandStore.warn("could not read " + mk + " - the 0.5.3 default update waits for the next start"); return -1; }
    if (done.getProperty(MIG_STEP) != null) return -1;
    java.util.Properties p = readProps(FILE);
    if (p == null) { @PKG@.IslandStore.warn("could not read config.properties - the 0.5.3 default update waits for the next start"); return -1; }
    java.util.HashSet seen = loggedKeys(FILE.resolveSibling("config-changes.log"), MIG_BY);
    if (seen == null) { @PKG@.IslandStore.warn("could not read config-changes.log - the 0.5.3 default update waits for the next start (it must know which values an admin set)"); return -1; }
    int mask = 0;
    String[] note = new String[MIG_KEYS.length];
    for (int i = 0; i < MIG_KEYS.length; i++) {
      String raw = p.getProperty(MIG_KEYS[i]);
      String v = raw == null ? "" : raw.trim();
      if (v.length() == 0) note[i] = "no line - the new default " + MIG_NEW[i] + " applies";
      else if (v.equals(MIG_NEW[i])) note[i] = "already " + MIG_NEW[i];
      else if (!v.equals(MIG_OLD[i])) note[i] = "kept " + plain(v, 40) + " (an admin's value)";
      else if (seen.contains(MIG_KEYS[i])) note[i] = "kept " + MIG_OLD[i] + " (an admin set it - config-changes.log)";
      else { mask = mask | (1 << i); note[i] = "old default " + MIG_OLD[i]; }
    }
    MIG_NOTE = note;
    return mask;
  } catch (Throwable t) { @PKG@.IslandStore.warn("the 0.5.3 default update was skipped this start (it runs again next start): " + t); return -1; }
}""")
# tmp + fsync + atomic rename (plain replace fallback), 5 x 20 ms retries on a Windows sharing violation; false = not written
M(cfg, r"""
public static boolean writeText(java.nio.file.Path f, String text) {
  java.nio.file.Path tmp = f.resolveSibling(f.getFileName().toString() + ".tmp");
  boolean ok = false;
  try {
    java.nio.file.Files.createDirectories(f.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.io.FileOutputStream out = new java.io.FileOutputStream(tmp.toFile());
    try {
      out.write(text.getBytes("ISO-8859-1"));
      out.flush();
      out.getFD().sync();
    } finally { out.close(); }
    for (int i = 0; i < 5 && !ok; i++) {
      try {
        try {
          java.nio.file.Files.move(tmp, f, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING, java.nio.file.StandardCopyOption.ATOMIC_MOVE });
        } catch (java.nio.file.AtomicMoveNotSupportedException a) {
          java.nio.file.Files.move(tmp, f, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
        }
        ok = true;
      } catch (java.nio.file.FileSystemException e) {
        try { Thread.sleep(20L); } catch (Throwable ie) { }
      }
    }
  } catch (Throwable t) { ok = false; }
  if (!ok) { try { java.nio.file.Files.deleteIfExists(tmp); } catch (Throwable t) { } }
  return ok;
}""")
# records the step in migrations.properties (other lines of the file are kept); false = not written (the step runs again next start)
M(cfg, r"""
public static boolean markDone(String summary) {
  try {
    if (FILE == null) return false;
    java.nio.file.Path mk = FILE.resolveSibling("migrations.properties");
    String old = "";
    if (java.nio.file.Files.exists(mk, new java.nio.file.LinkOption[0])) old = new String(java.nio.file.Files.readAllBytes(mk), "ISO-8859-1");
    else old = "# SkyyIslands one-time update steps. Each listed step has run and does not run again. Do not edit.\n";
    if (old.length() > 0 && !old.endsWith("\n")) old = old + "\n";
    String when = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss").format(java.time.LocalDateTime.now());
    return writeText(mk, old + MIG_STEP + "=" + when + " | " + plain(summary, 600) + "\n");
  } catch (Throwable t) { return false; }
}""")

