# 0.5.6 (Hytale 0.7): the chunk is a ref in the ChunkStore; its BlockChunk / WorldChunk are components of that ref (= ChunkTintCommand).
# World thread. idx = ChunkUtil.indexChunk(cx, cz); a chunk that is not loaded (no ref / invalid ref) = 0 columns (0.5.5: getChunkIfLoaded null)
M(tint, r"""
public static int tintChunk(@WLD@ w, long idx) {
  int n = 0;
  try {
    @CST@ cs = w.getChunkStore();
    @REF@ r = cs.getChunkReference(idx);
    if (r == null || !r.isValid()) return 0;
    @ST@ st = cs.getStore();
    @BCH@ bc = (@BCH@) st.getComponent(r, @BCH@.getComponentType());
    if (bc == null) return 0;
    for (int x = 0; x < 32; x++) for (int z = 0; z < 32; z++) {
      if (bc.getTint(x, z) != GRASS) { bc.setTint(x, z, GRASS); n++; }
    }
    if (n > 0) {
      bc.markNeedsSaving();
      @WCH@ wc = (@WCH@) st.getComponent(r, @WCH@.getComponentType());
      if (wc != null) wc.markNeedsSaving();
    }
  } catch (Throwable t) { @PKG@.IslandStore.warn("tint failed: " + t); }
  return n;
}""")
M(tint, r"""
public static void resend(@WLD@ w, long idx) {
  int m = @PKG@.IslandCfg.TINT_RESEND;
  if (m == 0 || w == null) return;
  try {
    if (m == 2) w.getNotificationHandler().updateChunk(idx);
    else w.getNotificationHandler().updateChunkTints(idx);
  } catch (Throwable t) { @PKG@.IslandStore.warn("tint resend failed: " + t); }
}""")
# world thread: every loaded chunk within 2 chunks of (0,0); costs nothing when all columns are already green
M(tint, r"""
public static int fix(@WLD@ w) {
  int cols = 0;
  int chunks = 0;
  if (w == null) return 0;
  try {
    @CST@ cs = w.getChunkStore();
    for (int tx = -2; tx <= 2; tx++) for (int tz = -2; tz <= 2; tz++) {
      long idx = @CHU@.indexChunk(tx, tz);
      @REF@ c = cs.getChunkReference(idx);
      if (c == null || !c.isValid()) continue;
      int n = tintChunk(w, idx);
      if (n > 0) { resend(w, idx); cols += n; chunks++; }
    }
    if (cols > 0) @PKG@.IslandStore.info("re-tinted " + cols + " columns in " + chunks + " chunk(s) of " + w.getName() + (@PKG@.IslandCfg.TINT_RESEND == 0 ? " (resend off)" : (@PKG@.IslandCfg.TINT_RESEND == 2 ? " and resent those chunks" : " and sent the new tints to the clients")));
  } catch (Throwable t) { @PKG@.IslandStore.warn("tint fix failed: " + t); }
  return cols;
}""")

