# 0.5.3: the untouched old defaults IslandCfg.plan053 found are set through the kit's own path (validated, running value, History copy,
# config-changes.log 'ok' line with Undo, the kit's INFO line), by "SkyyIslands 0.5.3 update" via console, then written NOW
# (CfgPub.flush: the file line in place + RELOAD). The step is recorded (migrations.properties) only when every planned key applied and
# config.properties on disk holds the new value; else it runs again at the next start. Never throws. Island files: never touched.
M(hooks, r"""
public static String apply053(int mask) {
  if (mask < 0) return null;
  String[] keys = @PKG@.IslandCfg.MIG_KEYS;
  String[] note = @PKG@.IslandCfg.MIG_NOTE;
  boolean all = true;
  int applied = 0;
  String[] res = new String[keys.length];
  for (int i = 0; i < keys.length; i++) {
    res[i] = (note == null || i >= note.length || note[i] == null) ? "-" : note[i];
    if ((mask & (1 << i)) == 0) continue;
    Object[] r = null;
    if (@PKG@.CfgPub.STARTED) {
      try { r = @PKG@.CfgFn.set(keys[i], @PKG@.IslandCfg.MIG_NEW[i], null, @PKG@.IslandCfg.MIG_BY, "yes", "console"); } catch (Throwable t) { r = null; }
    }
    String st = (r == null || r.length < 1 || r[0] == null) ? "error" : String.valueOf(r[0]);
    if (st.equals("ok") || st.equals("restart")) {
      applied = applied | (1 << i);
      res[i] = @PKG@.IslandCfg.MIG_OLD[i] + " -> " + @PKG@.IslandCfg.MIG_NEW[i] + " (was the untouched old default)";
      @PKG@.IslandStore.info("config.properties: " + keys[i] + " was still the untouched old default " + @PKG@.IslandCfg.MIG_OLD[i] + " - now " + @PKG@.IslandCfg.MIG_NEW[i] + ": " + @PKG@.IslandCfg.MIG_WHY[i] + ". Server Setup -> Islands -> Changes lists it (Undo there goes back).");
    } else {
      all = false;
      String why = (r != null && r.length > 2 && r[2] != null) ? String.valueOf(r[2]) : (@PKG@.CfgPub.STARTED ? "see the server log" : "the config kit did not start");
      res[i] = "NOT changed yet (" + @PKG@.IslandCfg.plain(why, 120) + ") - tried again at the next start";
      @PKG@.IslandStore.warn("config.properties: " + keys[i] + " is still the old default " + @PKG@.IslandCfg.MIG_OLD[i] + " but could not be set to " + @PKG@.IslandCfg.MIG_NEW[i] + " (" + why + ") - tried again at the next start.");
    }
  }
  if (applied != 0) {
    try { @PKG@.CfgPub.flush(); } catch (Throwable t) { @PKG@.IslandStore.warn("0.5.3 default update: writing config.properties failed: " + t); }
    java.util.Properties p = @PKG@.IslandCfg.readProps(@PKG@.IslandCfg.FILE);
    for (int i = 0; i < keys.length; i++) {
      if ((applied & (1 << i)) == 0) continue;
      String v = p == null ? null : p.getProperty(keys[i]);
      if (v != null && v.trim().equals(@PKG@.IslandCfg.MIG_NEW[i])) continue;
      all = false;
      res[i] = res[i] + " - in use now, but config.properties does not show it yet (the kit retries the write every 30 s; this step looks again at the next start)";
      @PKG@.IslandStore.warn("config.properties: " + keys[i] + " is " + @PKG@.IslandCfg.MIG_NEW[i] + " in the running server, but the file does not show it yet - the config kit retries the write; the 0.5.3 default update looks again at the next start.");
    }
  }
  StringBuilder sum = new StringBuilder();
  for (int i = 0; i < keys.length; i++) {
    if (i > 0) sum.append(" | ");
    sum.append(keys[i]).append(": ").append(res[i]);
  }
  String out = sum.toString();
  if (all && !@PKG@.IslandCfg.markDone(out)) @PKG@.IslandStore.warn("could not write migrations.properties - the 0.5.3 default update looks again at the next start (it only ever changes values that are still the untouched old defaults).");
  @PKG@.IslandStore.info("0.5.3 default update (Skyy's 2026-09-25 island locks)" + (all ? "" : " - NOT finished, runs again at the next start") + ": " + out);
  return out;
}""")

