M(ieng, r"""
public int goHome(String wn, java.util.UUID u, String hk, String home) {
  @PR@ pr = @PKG@.IslandStore.online(u);
  if (pr == null || home == null || hk == null) return 0;
  @REF@ r = pr.getReference();
  if (r == null || !r.isValid()) return 0;
  @ST@ st = r.getStore();
  @WLD@ from = world(wn);
  if (from == null) return 0;
  @WLD@ w2 = world(home);
  // 0.5.20 (bug 1): already in the island's world = the engine's respawn put them at their bed there or the island spawn - never a
  // second, same-world teleport (0.5.15-0.5.19 teleported again 1.8 s later, onto the raw bed cell)
  if (w2 != null && w2 == from) return 4;
  if (w2 != null) {
    @TRF@ where = null;
    int how = 2;
    @PRP@[] pts = points(u, home);
    if (pts != null && pts[0].getRespawnPosition() != null) {
      @V3D@ p = pts[0].getRespawnPosition();
      where = new @TRF@(p.x, p.y + 1.0, p.z, 0.0f, 0.0f, 0.0f);   // 0.5.20: only if the island's thread cannot take the job (below)
      how = 1;
      // 0.5.20 (bug 2): the landing spot is collision-checked on the island's own thread first (IsleTask 13), then teleported here (14)
      @PKG@.IsleTask bt = new @PKG@.IsleTask(13, home, u);
      bt.a = wn;
      bt.x = p.x;
      bt.y = p.y;
      bt.z = p.z;
      org.joml.Vector3i bp = pts[0].getBlockPosition();
      bt.bx = bp != null ? bp.x : (int) Math.floor(p.x);
      bt.by = bp != null ? bp.y : (int) Math.floor(p.y);
      bt.bz = bp != null ? bp.z : (int) Math.floor(p.z);
      if (exec(home, bt)) return 1;
    } else {
      try {
        java.util.concurrent.CompletableFuture f = w2.getWorldConfig().getSpawnProvider().getSpawnPointAsync(w2, u);
        if (f != null && f.isDone()) { Object o = f.getNow(null); where = (o instanceof @TRF@) ? (@TRF@) o : null; }
      } catch (Throwable t) { where = null; }
    }
    // 0.5.20 review: the same-world branches (0.5.15's 2-block check, the -2 retry) are gone - the same world returned 4 above
    if (where != null) {
      try {
        ((@CA@) st).addComponent(r, @TP@.getComponentType(), @TP@.createForPlayer(w2, where));
        return how;
      } catch (Throwable t) {
        @PKG@.IslandStore.warn("respawn teleport to the island failed (using /island instead): " + t);
      }
    }
  }
  @PKG@.IslandCmd.go(st, r, pr, from, hk, hk.equals(@PKG@.IslandStore.pkey(u)));
  return 3;
}""")
