# 0.5.20 (bug 2): a free spot for the player at x,y,z of an island world (its thread): feet + head air (or grass / a flower) and no fluid, solid ground
# under it; 1 = free, 0 = blocked, -1 = a cell not loaded
M(ilif, r"""
public static boolean airish(String b) {
  return b != null && (b.length() == 0 || b.startsWith("Plant_Grass") || b.startsWith("Plant_Flower"));
}""")
M(ilif, r"""
public static int freeAt(String wn, int x, int y, int z) {
  @PKG@.IsleApi a = api();
  String f = a.block(wn, x, y, z);
  String h = a.block(wn, x, y + 1, z);
  String g = a.block(wn, x, y - 1, z);
  if (f == null || h == null || g == null) return -1;
  if (!airish(f) || !airish(h)) return 0;
  int ff = a.fluid(wn, x, y, z);
  int fh = a.fluid(wn, x, y + 1, z);
  if (ff < 0 || fh < 0) return -1;
  if (ff != 0 || fh != 0) return 0;                       // review fix: never feet / head in water
  return (g.length() > 0 && !g.startsWith("Plant_")) ? 1 : 0;
}""")
# the engine's bed rule (Player.ensureNoCollisionAtRespawnPosition): the respawn position, else the rings 1 and 2 around the bed block
# (its height, then one up); null = a cell not loaded; no free cell = the raw position one block up
M(ilif, r"""
public static double[] bedSpot(String wn, double rx, double ry, double rz, int bx, int by, int bz) {
  int f0 = freeAt(wn, (int) Math.floor(rx), (int) Math.floor(ry), (int) Math.floor(rz));
  if (f0 < 0) return null;
  if (f0 == 1) return new double[] { rx, Math.floor(ry), rz };
  for (int r = 1; r <= 2; r++) {
    for (int dy = 0; dy <= 1; dy++) {
      for (int dx = -r; dx <= r; dx++) {
        for (int dz = -r; dz <= r; dz++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) != r) continue;
          int f = freeAt(wn, bx + dx, by + dy, bz + dz);
          if (f < 0) return null;
          if (f == 1) return new double[] { (double) (bx + dx) + 0.5, (double) (by + dy), (double) (bz + dz) + 0.5 };
        }
      }
    }
  }
  return new double[] { rx, ry + 1.0, rz };
}""")
