# 0.5.23: RespawnEvent (the death world's thread, BEFORE the engine respawns): 1 = cancel the vanilla respawn (ours is on its way), 0 = leave
# it to the engine (+ the 0.5.20 trip 1.8 s later). Only route 1 (a death elsewhere -> their island, no bed where they died) with the
# island world loaded; everything else exactly as 0.5.22. Review fix 1: ONE attempt per death - a click within 3 s of it is swallowed (chat
# line), a click 3 s+ later while still dead = the attempt is given up and the vanilla respawn runs (never retried for this death);
# an attempt older than 60 s belongs to an earlier death (forgotten)
M(ilif, r"""
public static int early(String dw, java.util.UUID u) {
  if (!@PKG@.IslandCfg.RESPAWN_HOME || dw == null || u == null) return 0;
  @PKG@.IsleApi a = api();
  long now = a.now();
  Object b = BYPASS.remove(u);
  if (b instanceof Long && now - ((Long) b).longValue() < EARLY_TTL) return 0;     // our own fallback call: the vanilla respawn
  Object p = EARLY.get(u);
  if (p instanceof Long) {
    long age = now - ((Long) p).longValue();
    if (age >= 0L && age < EARLY_WAIT) {
      a.say(u, "[Island] Taking you to your island...", "#cfe3ff");             // review fix 2
      return 1;
    }
    EARLY.remove(u);
    if (age >= 0L && age < EARLY_OLD) {
      @PKG@.IslandStore.info("respawn " + a.name(u) + ": the respawn onto the island did not arrive in " + (age / 1000L) + " s - the normal respawn + the trip home instead");
      a.say(u, "[Island] Could not respawn you on your island - respawning here, the trip home follows.", "#ff9d6b");   // review fix 2
      return 0;
    }
  }
  if (deathKeep(dw)) return 0;
  String hk = @PKG@.IslandStore.homeKey(u);
  @PKG@.IslandSettings s = @PKG@.IslandStore.settings(hk);
  if (s == null || s.bad || s.world == null || s.world.equals(dw)) return 0;
  if (route(dw, s.world, a.hasBed(u, dw), a.hubWorld(), true) != 1) return 0;
  EARLY.put(u, Long.valueOf(now));
  if (a.earlyTrip(dw, u, s.world) <= 0) { EARLY.remove(u); return 0; }
  return 1;
}""")
