# 0.5.15: the old ruins bed, once per 3-island island: already there (a new / reset island's layout) -> remembered; all 12 cells empty
# air and the 6 ground cells still the generator's grass / dirt -> placed; anything else (a player's blocks) -> never (bed.placed=skip).
# A cell not loaded = later.
M(ilif, r"""
public static int bedOnce(String wn, String owner, @PKG@.IsleState st) {
  if (st.bedDone) return 0;
  if (fileHas(owner, "bed.placed", "1") || fileHas(owner, "bed.placed", "skip")) { st.bedDone = true; return 0; }
  @PKG@.IsleApi a = api();
  String o = a.block(wn, BEDP[0], BEDP[1], BEDP[2]);
  if (o == null) return 0;
  String v = "1";
  if (!BED_ID.equals(o)) {
    for (int i = 0; i + 2 < BED_CELLS.length; i += 3) {
      String b = a.block(wn, BED_CELLS[i], BED_CELLS[i + 1], BED_CELLS[i + 2]);
      if (b == null) return 0;
      if (b.length() > 0) v = "skip";
    }
    for (int i = 0; i + 2 < BED_GROUND.length; i += 3) {
      String b = a.block(wn, BED_GROUND[i], BED_GROUND[i + 1], BED_GROUND[i + 2]);
      if (b == null) return 0;
      if (!"Soil_Grass".equals(b) && !"Soil_Dirt".equals(b)) v = "skip";
    }
    if (v.equals("1")) {
      if (!a.setBlock(wn, BEDP[0], BEDP[1], BEDP[2], BED_ID)) { warnOnce("bed", "could not place the old bed on an island (logged once)"); v = "skip"; }
      else { BEDS.incrementAndGet(); a.relight(wn); }
    }
  }
  st.bedDone = true;
  saveProps(owner, new String[] { "bed.placed" }, new String[] { v });
  return v.equals("1") && !BED_ID.equals(o) ? 1 : 0;
}""")
