# tracked skeletons go; the tracked Shardkeeper stopped after the quest (and not needed for a broken portal) = it goes too
M(ilif, r"""
public static int clearTick(String wn, @PKG@.IsleState st, java.util.ArrayList mem, long now) {
  if (!@PKG@.IslandCfg.CAMP_CLEAR) return 0;
  if (st.clearAt != 0L && now - st.clearAt >= 0L && now - st.clearAt < 10000L) return 0;
  st.clearAt = now;
  int n = 0;
  if (@PKG@.IslandCfg.CAMP_ON && @PKG@.IslandCfg.CAMP_STOP && !st.camp.isEmpty() && campDone(wn, st, now))
    n += clearIds(wn, st.camp, anyNear(mem, CAMP[0], CAMP[2], LOADED_R));                        // 0.5.22: kept while not loaded
  if (@PKG@.IslandCfg.BOSS_ON && st.boss != null && st.bossMine && @PKG@.IslandCfg.BOSS_STOP && bossDone(wn, st, now) && !bossNeeded(wn, st, mem)) {
    java.util.HashSet one = new java.util.HashSet();
    one.add(st.boss);
    n += clearIds(wn, one, anyNear(mem, BOSS[0], BOSS[2], LOADED_R));                             // 0.5.22: only OUR Shardkeeper
    if (one.isEmpty()) { st.boss = null; st.bossMine = false; }
  }
  if (n > 0) {
    CLEARED.addAndGet((long) n);
    @PKG@.IslandStore.info("cleared " + n + " camp / mini boss mob(s) on " + wn + " (the quest is done; Server Setup: Clear the camp when the quest is done)");
  }
  return n;
}""")
