# 0.5.22: once per world per run - the island file's camp.ids / boss.id (ours from before a restart) join the tracked ids
M(ilif, r"""
public static void loadIds(String wn, @PKG@.IsleState st, String owner) {
  if (st.idsLoaded) return;
  st.idsLoaded = true;
  try {
    @PKG@.IslandSettings s = @PKG@.IslandStore.settings(owner);
    if (s != null && !s.bad && s.raw != null) {
      String c = s.raw.getProperty("camp.ids", "");
      String[] p = c.split(",");
      for (int i = 0; i < p.length && st.camp.size() < 40; i++) {
        String t = p[i].trim();
        if (t.length() == 0) continue;
        try { st.camp.add(java.util.UUID.fromString(t).toString()); } catch (Throwable u) { }
      }
      String b = s.raw.getProperty("boss.id", "").trim();
      if (b.length() > 0 && st.boss == null) {
        try { st.boss = java.util.UUID.fromString(b).toString(); st.bossMine = true; } catch (Throwable u) { }
      }
    }
  } catch (Throwable t) { warnOnce("ids", "reading the saved camp / boss ids failed (logged once): " + t); }
  st.idsSaved = campCsv(st) + "|" + (st.bossMine && st.boss != null ? st.boss : "");
}""")
# 0.5.22: written only when they changed (a spawn, a death, a removal); an empty value removes the key
M(ilif, r"""
public static void saveIds(String owner, @PKG@.IsleState st) {
  if (!st.idsLoaded || owner == null) return;
  String c = campCsv(st);
  String b = st.bossMine && st.boss != null ? st.boss : "";
  String k = c + "|" + b;
  if (k.equals(st.idsSaved)) return;
  st.idsSaved = k;
  saveProps(owner, new String[] { "camp.ids", "boss.id" }, new String[] { c.length() == 0 ? null : c, b.length() == 0 ? null : b });
}""")
# 0.5.20 THE POND, once per 3-island island (review fixes): pond.placed = (none) | inprogress.N (a run started: air in the dug cells is
# ours) | 1 | skip (a foreign block, logged) | gaveup (logged). A run starts only when every dug + floor cell is the old island's
