# 0.5.24 IsleUnload part 2. limitMs: how long a world must stay empty (-1 = never: the setting is 0); retired worlds at most 60 s
M(iunl, r"""
public static long limitMs(boolean retired) {
  int s = @PKG@.IslandCfg.UNLOAD_S;
  if (s <= 0) return -1L;
  long l = 1000L * (long) s;
  if (retired && l > RETIRED_MS) l = RETIRED_MS;
  return l;
}""")
# decide (pure logic, any thread): 0 = keep (its empty clock reset), 1 = wait (empty clock running), 2 = unload now.
# players = World.getPlayerCount(); homes = the active home island keys of every online player (IslandStore.homeKey)
M(iunl, r"""
public static int decide(String wn, int players, java.util.Set homes, long now) {
  if (wn == null) return 0;
  if (players > 0) SEEN.put(wn, Long.valueOf(now));      // review fix 2: any player inside (visitors, admins) counts
  if (players > 0 || !@PKG@.IslandStore.isIslandWorld(wn) || NEVER.containsKey(wn)) { EMPTY.remove(wn); return 0; }
  String owner = @PKG@.IslandStore.ownerOf(wn);
  if (owner == null || @PKG@.IslandStore.CREATING.containsKey(owner) || @PKG@.IslandStore.RESETTING.containsKey(owner)) { EMPTY.remove(wn); return 0; }
  boolean retired = @PKG@.IslandStore.isRetired(wn);
  long lim = limitMs(retired);
  if (lim < 0L) { EMPTY.remove(wn); return 0; }
  if (!retired) {
    @PKG@.IslandSettings s = @PKG@.IslandStore.settings(owner);
    if (s == null || s.bad || s.world == null || !s.world.equals(wn)) { EMPTY.remove(wn); return 0; }
    if (homes != null && homes.contains(owner)) { EMPTY.remove(wn); return 0; }
  }
  Object u = USED.get(wn);
  if (u instanceof Long && now - ((Long) u).longValue() >= 0L && now - ((Long) u).longValue() < USE_GRACE) { EMPTY.remove(wn); return 0; }
  // review fix 2: never while ANY player was inside within the full setting (a visitor gone to a shard / zone may come back by its
  // return point, an admin /tp, another mod's teleport) - retired worlds too
  Object sn = SEEN.get(wn);
  if (sn instanceof Long && now - ((Long) sn).longValue() >= 0L && now - ((Long) sn).longValue() < limitMs(false)) { EMPTY.remove(wn); return 0; }
  Object since = EMPTY.get(wn);
  if (!(since instanceof Long) || now - ((Long) since).longValue() < 0L) { EMPTY.put(wn, Long.valueOf(now)); return 1; }
  return now - ((Long) since).longValue() >= lim ? 2 : 1;
}""")
# unload one world now (the sweep's scheduler thread; Universe.removeWorld saves it like a server stop, ~0.1 s, the folder stays).
# 1 = unloaded, 0 = left loaded (someone came, a mod cancelled), -1 = refused / failed (left as it is)
M(iunl, r"""
public static int unload(String wn) {
  if (wn == null || BUSY.putIfAbsent(wn, Boolean.TRUE) != null) return 0;
  int r = 0;
  try {
    @UNI@ uni = @UNI@.get();
    @WLD@ w = uni == null ? null : uni.getWorld(wn);
    long now = System.currentTimeMillis();
    Object u = USED.get(wn);
    boolean used = u instanceof Long && now - ((Long) u).longValue() >= 0L && now - ((Long) u).longValue() < USE_GRACE;
    if (w == null || !w.isAlive() || w.getPlayerCount() > 0 || used) r = 0;
    else {
      @WCFG@ c = w.getWorldConfig();
      if (c == null || c.isDeleteOnRemove() || c.isDeleteOnUniverseStart()) {
        NEVER.put(wn, Boolean.TRUE);
        @PKG@.IslandStore.warn("island world " + wn + " is NOT unloaded: its config.json says delete on remove / on start - it stays loaded, nothing is deleted");
        r = -1;
      } else {
        boolean retired = @PKG@.IslandStore.isRetired(wn);
        if (uni.removeWorld(wn)) {
          UNLOADS.incrementAndGet();
          @PKG@.IslandStore.info("island world " + wn + " unloaded in " + (System.currentTimeMillis() - now) + " ms - " + (retired ? "an old world from an island reset (kept on disk as a backup)" : "nobody there for " + @PKG@.IslandCfg.UNLOAD_S + " s and nobody of that island online") + "; saved first, the folder stays; it loads again when someone goes there");
          r = 1;
        } else {
          @PKG@.IslandStore.warn("island world " + wn + " was not unloaded (a mod cancelled it) - it stays loaded");
          r = 0;
        }
      }
    }
  } catch (Throwable t) {
    @PKG@.IslandStore.warn("unloading island world " + wn + " failed (left as it is): " + t);
    r = -1;
  }
  BUSY.remove(wn);
  EMPTY.remove(wn);
  if (r == 1) LOADING.remove(wn);                   // review fix 1: never pin the old World through a finished load future
  return r;
}""")
# the 30 s sweep (scheduler thread): every LOADED registered island world through decide; at most PER_SWEEP unloads a sweep (the engine
# loads every world folder at start, so several fall due together - SkyyShards' UNLOAD_PER_TICK); forgets clocks of unloaded worlds
M(iunl, r"""
public static int sweep() {
  Object[] lk = LOADING.keySet().toArray();         // review fix 1: a load future is kept only while the load runs
  for (int i = 0; i < lk.length; i++) {
    Object f = LOADING.get(lk[i]);
    if (!(f instanceof java.util.concurrent.CompletableFuture) || ((java.util.concurrent.CompletableFuture) f).isDone()) LOADING.remove(lk[i]);
  }
  if (SEEN.size() > 4096) SEEN.clear();
  if (@PKG@.IslandCfg.UNLOAD_S <= 0) { EMPTY.clear(); return 0; }
  @UNI@ uni = @UNI@.get();
  if (uni == null) return 0;
  long now = System.currentTimeMillis();
  java.util.HashSet homes = new java.util.HashSet();
  Object[] ps = uni.getPlayers().toArray();
  for (int i = 0; i < ps.length; i++) {
    if (!(ps[i] instanceof @PR@)) continue;
    try {
      String hk = @PKG@.IslandStore.homeKey(((@PR@) ps[i]).getUuid());
      if (hk != null) homes.add(hk);
    } catch (Throwable t) { }
  }
  Object[] ws = uni.getWorlds().values().toArray();
  java.util.HashSet live = new java.util.HashSet();
  int n = 0;
  for (int i = 0; i < ws.length; i++) {
    if (!(ws[i] instanceof @WLD@)) continue;
    @WLD@ w = (@WLD@) ws[i];
    String wn = w.getName();
    if (wn == null) continue;
    live.add(wn);
    if (!w.isAlive() || busy(wn)) continue;
    if (decide(wn, w.getPlayerCount(), homes, now) != 2 || n >= PER_SWEEP) continue;
    if (unload(wn) == 1) n++;
  }
  Object[] ks = EMPTY.keySet().toArray();
  for (int i = 0; i < ks.length; i++) if (!live.contains(ks[i])) EMPTY.remove(ks[i]);
  return n;
}""")
M(iunl, r"""
public void run() {
  try {
    if (this.mode == 0) sweep();
  } catch (Throwable t) { @PKG@.IsleLife.warnOnce("unload", "the empty-island unload sweep failed (logged once; worlds stay loaded): " + t); }
}""")
